SELECT * FROM tb_photo
WHERE user_seq = #{userSeq}
  AND is_deleted = 0

    AND photo_type = #{photoType}

ORDER BY created_at DESC

mapper.update:
UPDATE tb_photo
SET is_main = CASE WHEN photo_seq = #{photoSeq} THEN 1 ELSE 0 END
WHERE user_seq   = #{userSeq}
  AND photo_type = #{photoType}
  AND is_deleted = 0

UPDATE tb_photo
SET is_deleted = 1
WHERE photo_seq = #{photoSeq}
  AND user_seq  = #{userSeq}
